#!/usr/bin/env python3\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parents[2]\nPLAYER = (ROOT / "web" / "player.html").read_text(encoding="utf-8")\nDESIGN = (ROOT / "design" / "角色装配备忘_用什么×怎么装×可变层_2026-08-03.md").read_text(encoding="utf-8")\n\n\ndef test_player_defaults_to_free_stage():\n    assert 'engine: "free_stage"' in PLAYER\n    state_block = PLAYER.split("const state = {", 1)[1].split("};", 1)[0]\n    assert 'engine: "scene"' not in state_block\n\n\ndef test_legacy_scene_requires_explicit_query_switch():\n    assert 'params.get("legacy_scene") === "1"' in PLAYER\n    legacy_block = PLAYER.split('params.get("legacy_scene") === "1"', 1)[1][:500]\n    assert 'state.engine = "scene"' in legacy_block\n    assert "else {" in legacy_block\n    assert 'state.engine = "free_stage"' in legacy_block\n\n\ndef test_skip_prologue_respects_selected_engine():\n    block = PLAYER.split('params.get("skip_prologue") === "1"', 1)[1][:700]\n    assert 'state.engine === "free_stage"' in block\n    assert "startFreeStage();" in block\n    assert "startScene();" in block\n\n\ndef test_design_and_runtime_agree_on_main_path():\n    assert "旁路（不是现玩法主路径）" in DESIGN\n    assert "/api/scene" in DESIGN and "旧薄 prompt" in DESIGN\n    assert "主路径：" in DESIGN and "/api/free_stage" in DESIGN\n\n\nif __name__ == "__main__":\n    for name in sorted(n for n in globals() if n.startswith("test_")):\n        globals()[name]()\n        print("PASS", name)\n